const AccountTypeCard = ({
  body,
  checked = false,
  recommended = false,
  title,
  value,
}) => {
  const className = [
    "account-hub-account-type-card",
    recommended ? "recommended" : "",
  ]
    .filter(Boolean)
    .join(" ");

  return html`
    <label class=${className}>
      <input
        type="radio"
        name="account-type"
        value="${value}"
        ${checked ? 'checked="checked"' : ""}
      />
      <span class="account-hub-account-type-card-content">
        <span
          class="account-hub-account-type-card-badge"
          data-l10n-id="account-hub-result-recommended-label"
          >Recommended</span
        >
        <span class="account-hub-account-type-card-header">
          <div class="account-hub-account-type-card-icon"></div>
          <span>${title}</span>
        </span>
        <span
          class="account-hub-account-type-card-body"
          data-l10n-id="account-hub-protocol-${value}"
          >${body}</span
        >
      </span>
    </label>
  `;
};

const AccountTypeCards = ({ title, body }) => html`
  <form class="account-hub-account-type-card-story">
    <fieldset class="account-hub-account-type-list">
      ${AccountTypeCard({
        body,
        checked: true,
        recommended: true,
        title,
        value: "imap",
      })}
      ${AccountTypeCard({
        body: html`Exchange<br />or<br />Microsoft 365`,
        title: "Microsoft",
        value: "microsoft",
      })}
      ${AccountTypeCard({
        body: "Download to device",
        title: "POP3",
        value: "pop3",
      })}
    </fieldset>
  </form>
`;

export const Default = AccountTypeCards.bind({});
